"""Actual DOM roster fingerprint and controls against current computed catalog results."""
from daily22 import ROOT,RUN,read,write,now
import json,subprocess
script=r'''const fs=require('fs'),crypto=require('crypto'),base=process.argv[1],pair=JSON.parse(fs.readFileSync(base+'/live-pair.json')),expected=JSON.parse(fs.readFileSync(base+'/expected-live-searches.json'));
function fingerprint(a){const s=JSON.stringify(a.map(x=>[x.title,x.center]).sort((a,b)=>JSON.stringify(a)<JSON.stringify(b)?-1:1));let h=2166136261,k=5381;for(let i=0;i<s.length;i++){h=Math.imul(h^s.charCodeAt(i),16777619);k=(Math.imul(k,33)^s.charCodeAt(i))|0;}return {value:(h>>>0).toString(16).padStart(8,'0')+(k>>>0).toString(16).padStart(8,'0'),characters:s.length,sha256:crypto.createHash('sha256').update(s).digest('hex')};}
console.log(JSON.stringify(expected.cases.map(c=>{const d=pair.cases.find(x=>x.country===c.country),f=Object.fromEntries(d.fields.map(x=>[x.name,x.value])),want=fingerprint(c.records),same=want.sha256===d.fingerprint.sha256&&want.value===d.fingerprint.value&&want.characters===d.fingerprint.characters&&d.actual_count===c.count,controls=f.species==='Dog'&&f.country===c.country&&f.cancer==='Cancer — any type'&&f.diagnosis_status==="I don't know"&&['age','weight','zip_code','approach'].every(k=>f[k]==='')&&d.preferences.length===6&&d.preferences.every(x=>x.checked);return {country:c.country,actual_browser_at:d.at,actual_count:d.actual_count,expected_count:c.count,actual_roster_fingerprint:d.fingerprint,expected_roster_fingerprint:want,whole_rendered_roster_fingerprint_equal:same,all_requested_controls_verified:controls,script_version_verified:d.script==='./matcher.js?v=clinical-gi-20261022',status:same&&controls?'PASS':'FAIL'};})));'''
cases=json.loads(subprocess.check_output(['node','-e',script,str(RUN)],cwd=ROOT,text=True));result=dict(comparison_at=now(),method=read(RUN/'live-pair.json')['method'],cases=cases,overall='PASS' if all(c['status']=='PASS' for c in cases) else 'FAIL',production_commit=read(RUN/'publication.json')['main_commit'],evidence_file=str((RUN/'live-pair.json').relative_to(ROOT)));write(RUN/'live-search-evidence.json',result);print(json.dumps(result))
